import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>SVG, logolar ve simgeler için en esnek formattır. Vektör olduğu için her boyutta keskin görünür; ama her program onu açamaz.</p>\n<p>PNG'ye dönüştürmek, vektör grafiği piksel grafiğe çevirir. Doğru ölçeği seçerseniz sonuç her yerde açılan, keskin bir görsel olur.</p>\n<p>Bu kılavuz, SVG'nin ne olduğunu, rasterleştirmenin ne demek olduğunu ve ölçek, saydamlık, yazı tipi ile renk konularında nelere dikkat edeceğinizi anlatıyor.</p>\n<h2 id=\"what-is-svg\">SVG dosyası nedir?</h2>\n<p>SVG, ölçeklenebilir vektör grafiği demektir. Görseli piksellerle değil, matematiksel şekillerle tanımlar; bu yüzden her boyutta keskindir.</p>\n<p>SVG dosyaları metin tabanlıdır. Bir metin düzenleyicide açıp renkleri ya da şekilleri elle değiştirebilirsiniz.</p>\n<p>Logolar, simgeler ve basit çizimler için idealdir. Fotoğraflar için uygun değildir; fotoğraf piksel ister.</p>\n<h2 id=\"what-is-rasterizing\">Rasterleştirmek ne demek?</h2>\n<p>Rasterleştirmek, vektör şekilleri piksel ızgarasına çevirmektir. SVG'nin matematiksel tanımı, belirli bir boyutta piksel haritasına dönüşür.</p>\n<p>Bu işlem tek yönlüdür. PNG'ye çevrilen bir SVG, artık vektör değildir; büyütüldüğünde pikseller görünür.</p>\n<p>Bu yüzden dönüştürmeden önce doğru boyutu seçmek çok önemlidir. Küçük üretilen bir PNG sonradan büyütülemez.</p>\n<h2 id=\"choosing-scale\">Doğru ölçeği seçmek</h2>\n<p>Ölçek, çıktı boyutunu belirler. 24 piksellik bir simgeyi 2x ölçekle dönüştürürseniz 48 piksellik keskin bir PNG alırsınız.</p>\n<p>Retina ekranlar için 2x ya da 3x kullanın. Standart ekranlarda 1x yeterli olur ama yüksek yoğunluklu ekranlarda bulanık görünür.</p>\n<p>Baskı için daha büyük ölçek gerekir. 300 DPI baskıda, santimetre başına yeterli piksel için 4x ya da üzeri ölçek seçin.</p>\n<h2 id=\"transparency-preserved\">Saydamlık korunur</h2>\n<p>SVG'deki saydam alanlar PNG'de de saydam kalır. Logo, her arka plan üzerinde temiz görünür.</p>\n<p>Dönüştürmeden sonra saydamlığı kontrol edin. Önizlemede saydam alanlar damalı desenle görünür.</p>\n<p>Beyaz arka planlı bir PNG istemiyorsanız saydamlık ayarını kontrol edin. Bazı araçlar varsayılan olarak beyaz arka plan ekler.</p>\n<h2 id=\"fonts-and-text\">SVG içindeki yazı tipleri ve metin</h2>\n<p>SVG'deki metin, sistemde yüklü yazı tipine dayanır. Yazı tipi yüklü değilse dönüştürücü yedek bir yazı tipi kullanır.</p>\n<p>Web yazı tipleri sorun çıkarabilir. Dönüştürücü, web yazı tipini yükleyemezse metin farklı görünür.</p>\n<p>En güvenli yol, metni yola dönüştürmektir. Metin yola dönüştürülürse yazı tipine gerek kalmaz ve her yerde aynı görünür.</p>\n<h2 id=\"linked-images\">Bağlantılı fotoğraflar ve dış dosyalar</h2>\n<p>Bazı SVG'ler dışarıdaki fotoğraflara bağlantı verir. Dönüştürücü bu dosyaya ulaşamazsa fotoğraf PNG'de eksik kalır.</p>\n<p>Çözüm, görseli SVG'ye gömmektir. Data URI olarak gömülen görsel, dönüştürmede kaybolmaz.</p>\n<p>Dönüştürmeden önce SVG'yi tarayıcıda açın. Eksik görsel varsa dönüştürmeden önce düzeltin.</p>\n<h2 id=\"gradients-and-opacity\">Degradeler, opaklık ve efektler</h2>\n<p>Degradeler ve opaklık genellikle sorunsuz dönüştürülür. Modern dönüştürücüler bu özellikleri doğru işler.</p>\n<p>Karmaşık filtreler sorun çıkarabilir. Bulanıklık ve gölge gibi efektler, dönüştürücüde farklı görünebilir.</p>\n<p>Şüphede kalırsanız sonucu önizlemede kontrol edin. Efektler bozuk görünüyorsa SVG'yi sadeleştirin.</p>\n<h2 id=\"batch-converting-icons\">Bir simge paketini toplu dönüştürmek</h2>\n<p>Bir simge paketini tek tek dönüştürmek zaman kaybıdır. Tüm SVG'leri aynı anda yükleyip toplu dönüştürün.</p>\n<p>Tüm simgeler için aynı ölçeği kullanın. Tutarlılık, setin her yerde aynı görünmesini sağlar.</p>\n<p>Dosya adları korunur; yalnızca uzantı değişir. Referansları güncellemek böylece kolaylaşır.</p>\n<h2 id=\"when-to-use-png-instead\">PNG'yi SVG yerine ne zaman kullanmalı?</h2>\n<p>Hedef program SVG açmıyorsa PNG kullanın. E-posta istemcileri, ofis programları ve eski yazılımlar PNG ister.</p>\n<p>Sosyal medya için PNG kullanın. Platformlar genellikle SVG kabul etmez; PNG her yerde açılır.</p>\n<p>Baskı için PNG kullanın. Baskı merkezleri PNG'yi kabul eder; SVG'yi reddedebilir.</p>\n<h2 id=\"colour-accuracy\">Dönüştürme renkleri değiştirir mi?</h2>\n<p>Genellikle hayır. SVG'deki renkler PNG'ye aynen aktarılır; renk kayması yaşanmaz.</p>\n<p>Marka renkleri kritikse karşılaştırın. Dönüştürülen PNG'yi orijinal SVG ile yan yana açıp renklerin aynı olduğunu doğrulayın.</p>\n<p>Degrade ve saydam renklerde küçük farklar olabilir. Şüphede kalırsanız renk seçiciyle kontrol edin.</p>\n<h2 id=\"file-sizes\">Dönüştürmeden sonra dosya boyutları</h2>\n<p>PNG, SVG'den genellikle daha büyüktür. Vektör tanımı küçük bir metindir; piksel haritası ise çok daha fazla veri tutar.</p>\n<p>Boyut, ölçekle birlikte büyür. 4x ölçekte üretilen PNG, 1x ölçeğin on altı katı piksel içerir.</p>\n<p>İhtiyacınız olan en küçük ölçeği seçin. Gereğinden büyük üretmek depolamayı ve yükleme süresini artırır.</p>\n<h2 id=\"common-problems\">Yaygın sorunlar ve çözümler</h2>\n<p>Bulanık PNG, genellikle düşük ölçekten kaynaklanır. Ölçeği artırıp yeniden dönüştürün.</p>\n<p>Eksik yazı tipi, metnin farklı görünmesine yol açar. Metni yola dönüştürün ya da yazı tipini yükleyin.</p>\n<p>Eksik fotoğraf, bağlantılı görselden kaynaklanır. Görseli SVG'ye gömün ve yeniden dönüştürün.</p>\n<h2 id=\"svg-logos-social-media\">Sosyal medya için SVG logoları</h2>\n<p>Sosyal platformlar SVG kabul etmez. Profil ve kapak görselleri için PNG'ye dönüştürün.</p>\n<p>Platformun istediği boyuta dikkat edin. Yanlış boyut kırpılır; önce boyut kurallarını öğrenin.</p>\n<p>Logo için 2x ölçek kullanın. Yüksek yoğunluklu ekranlarda keskin görünür.</p>\n<h2 id=\"svg-icons-apps\">Uygulamalar için SVG simgeleri</h2>\n<p>Uygulama simgelerini gereken her boyutta dönüştürün. Kaynak SVG vektör olduğu için her boyut keskin olur.</p>\n<p>Tüm boyutlarda aynı ölçek mantığını kullanın. Tutarlı bir set, uygulamada profesyonel görünür.</p>\n<p>Uygulama mağazaları kendi formatlarını isteyebilir. Mağaza listesi için istenen formatı kullanın.</p>\n<h2 id=\"svg-for-print-materials\">Basılı malzemeler için SVG</h2>\n<p>Baskı için yüksek ölçek gerekir. Kartvizit ve broşürde 300 DPI hedefleyin.</p>\n<p>Baskı merkezine sormaktan çekinmeyin. İstedikleri formatı ve çözünürlüğü öğrenmek, boşa baskıyı önler.</p>\n<p>Renk modunu kontrol edin. Baskıda CMYK gerekebilir; SVG genellikle RGB'dir.</p>\n<h2 id=\"svg-for-email-signatures\">E-posta imzaları için SVG</h2>\n<p>E-posta istemcileri SVG göstermez. İmza logosu için PNG'ye dönüştürün.</p>\n<p>İmza görseli küçük olmalıdır. PNG'yi boyutlandırmadan önce sıkıştırın.</p>\n<p>İmzayı farklı istemcilerde deneyin. Logo, her yerde aynı görünmelidir.</p>\n<h2 id=\"svg-for-favicons\">Favicon için SVG</h2>\n<p>Modern tarayıcılar SVG favicon destekler ama her tarayıcı desteklemez. Güvenli seçim, PNG favicon'dır.</p>\n<p>Favicon için 32x32 ve 16x16 boyutlarında PNG üretin. Küçük boyutlarda sade logolar daha iyi görünür.</p>\n<p>Favicon'ı tarayıcıda test edin. Sekmede net göründüğünden emin olun.</p>\n<p>Özetle: vektör kaynak, piksel teslimat. Dönüştürmek için <a href=\"/tr/svg-png-ye-donustur\">SVG'den PNG'ye aracını</a> açın; adımlar için <a href=\"/tr/blog/svg-png-ye-nasil-donusturulur\">SVG PNG'ye nasıl dönüştürülür</a> yazısına bakın. Karşılaştırma için <a href=\"/tr/blog/svg-vs-png-vektor-raster\">SVG ve PNG karşılaştırması</a> işinize yarar; genel dönüştürmeler için <a href=\"/tr/gorsel-donustur\">görsel dönüştürücü</a> de elinizin altındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"24 piksellik bir simgeyi keskin bir PNG'ye dönüştürmek için hangi ölçeği seçmeliyim?","answer":"Retina ekranlar için 2x ya da 3x ölçek kullanın; 24 piksellik simge 2x ölçekte 48 piksellik keskin bir PNG olur. Standart ekranlarda 1x yeterli olur ama yüksek yoğunluklu ekranlarda bulanık görünür. Baskı için 4x ya da üzeri gerekir."},{"question":"SVG'yi PNG'ye dönüştürmek saydam arka planı korur mu?","answer":"Evet. SVG'deki saydam alanlar PNG'de de saydam kalır; logo her arka plan üzerinde temiz görünür. Dönüştürmeden sonra önizlemede saydam alanların damalı desenle göründüğünü kontrol edin. Bazı araçlar varsayılan olarak beyaz arka plan ekler; ayarı kontrol edin."},{"question":"Dönüştürülen PNG'de bağlantılı fotoğraf neden eksik?","answer":"Çünkü SVG, dışarıdaki bir fotoğrafa bağlantı veriyordur ve dönüştürücü bu dosyaya ulaşamaz. Çözüm, görseli SVG'ye data URI olarak gömmektir. Dönüştürmeden önce SVG'yi tarayıcıda açıp eksik görsel olup olmadığını kontrol edin."},{"question":"SVG içinde web yazı tipi kullanıp PNG'ye aktarabilir miyim?","answer":"Genellikle hayır; dönüştürücü web yazı tipini yükleyemezse metin yedek bir yazı tipiyle görünür. En güvenli yol, metni yola dönüştürmektir. Metin yola dönüştürülürse yazı tipine gerek kalmaz ve her yerde aynı görünür."},{"question":"Bir SVG'den üretilebilecek en büyük PNG nedir?","answer":"Ölçek ve bellek sınırlar. Çoğu araç 8000 piksele kadar çıktı üretir; daha büyük boyutlar tarayıcıyı zorlayabilir. İhtiyacınız olan en küçük ölçeği seçin; gereğinden büyük üretmek yalnızca depolamayı artırır."},{"question":"Ortaya çıkan PNG kayıpsız mı?","answer":"Evet, PNG kayıpsız bir formattır; rasterleştirilen pikseller eksiksiz saklanır. Ancak dönüştürme tek yönlüdür: PNG artık vektör değildir ve büyütüldüğünde pikseller görünür. Bu yüzden dönüştürmeden önce doğru boyutu seçmek çok önemlidir."}];
